if (!customElements.get('ciam-link-nav')) {
    /**
    * @class CiamLinkNav
    * 
    * Causes to not blur the input if link was clicked to keep the virtual keyboard open
    * 
    * Works for iOS but not for Android
    */
    class CiamLinkNav extends HTMLElement {
        constructor () {
            super();
        }

        connectedCallback () {
            this.querySelectorAll('.link-nav').forEach(anchor => {
                anchor.addEventListener('mousedown', this._onMouseDown);
            });
        }

        disconnectedCallback () {
            this.querySelectorAll('.link-nav').forEach(anchor => {
                anchor.removeEventListener('mousedown', this._onMouseDown);
            });
        }

        _onMouseDown (e) {
            e.preventDefault()
        }
    }

    customElements.define('ciam-link-nav', CiamLinkNav);
}
